// Writes server/local/schema.generated.ts from shared/schema.ts (drizzle-kit is a devDependency,
// so the shop PC's server can't generate it at runtime). Re-run after any schema.ts change;
// scripts/verify-local-apply.ts fails if the committed file is stale.
import fs from "node:fs";
import path from "node:path";
import { schemaStatements } from "./lib/pgliteSchema";

export async function renderLocalSchemaFile(): Promise<string> {
  const stmts = await schemaStatements();
  return (
    "// GENERATED by scripts/gen-local-schema.ts from shared/schema.ts — do not edit.\n" +
    "// Re-run: npx tsx scripts/gen-local-schema.ts\n" +
    `export const LOCAL_SCHEMA_STATEMENTS: string[] = ${JSON.stringify(stmts, null, 2)};\n`
  );
}

export const LOCAL_SCHEMA_FILE = path.join(process.cwd(), "server", "local", "schema.generated.ts");

if (process.argv[1] && path.basename(process.argv[1]) === "gen-local-schema.ts") {
  renderLocalSchemaFile().then((text) => {
    fs.writeFileSync(LOCAL_SCHEMA_FILE, text);
    console.log(`wrote ${LOCAL_SCHEMA_FILE} (${text.length} bytes)`);
  });
}
